describe('ToolRegistry input validation', () => {
  it('returns a rejection for a missing required property without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather_lookup',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather_lookup', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/location.*required/i),
    });
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('names the expected type when rejecting a property with the wrong type', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_weather',
        description: 'Look up weather by location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('lookup_weather', {location: 42});

    expect({
      executorCalls,
      namesField: response.result.includes('/location'),
      namesExpectedType: response.result.includes('string'),
      omitsValue: !response.result.includes('42'),
    }).toEqual({executorCalls: 0, namesField: true, namesExpectedType: true, omitsValue: true});
  });
});
